/* Perplexity Kit Design Kit — Source Kit Layout — 77 tokens · 来源:design */
:root{
  --bg-100: #fafaf9;
  --bg-200: rgba(39, 26, 0, 0.07);
  --bg-300: #fafaf9;
  --text-100: rgb(39, 37, 30);
  --text-200: rgba(39, 37, 30, 0.65);
  --text-300: rgba(39, 37, 30, 0.45);
  --text-400: rgba(39, 37, 30, 0.45);
  --border-100: rgba(11,11,11,.06);
  --border-200: rgba(39, 26, 0, 0.08);
  --border-300: rgba(11,11,11,.1);
  --accent-main: #272520;
  --accent-hover: #272520;
  --font-sans: "PingFang SC","PingFang TC",-apple-system,BlinkMacSystemFont,"Hiragino Sans GB","Microsoft YaHei",sans-serif;
  --font-serif: "PingFang SC","PingFang TC",-apple-system,BlinkMacSystemFont,"Hiragino Sans GB","Microsoft YaHei",sans-serif;
  --font-brand: -apple-system, system-ui, "Segoe UI", sans-serif;
  --font-mono: ui-monospace, monospace;
  --fw-regular: 400;
  --fw-medium: 430;
  --fw-semibold: 560;
  --fw-bold: 700;
  --fs-xs: 11px;
  --fs-sm: 12px;
  --fs-base: 14px;
  --fs-md: 16px;
  --fs-lg: 20px;
  --fs-xl: 24px;
  --fs-2xl: 32px;
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 20px;
  --sp-6: 24px;
  --sp-8: 32px;
  --sp-10: 40px;
  --sp-12: 48px;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.04);
  --shadow-md: 0 2px 8px rgba(0,0,0,.06);
  --shadow-lg: 0 4px 16px rgba(0,0,0,.08);
  --motion-hover: 150ms;
  --motion-enter: 280ms;
  --motion-ease: cubic-bezier(.165,.85,.45,1);
  --motion-focus: 0 0 0 3px rgba(11,11,11,.08);
  --k-bg: var(--bg-100);
  --k-bg-grad: var(--bg-200);
  --k-card: #ffffff;
  --k-card-2: var(--bg-100);
  --k-card-3: var(--bg-200);
  --k-inset: var(--bg-200);
  --k-line: var(--border-100);
  --k-line-2: var(--border-200);
  --k-text: var(--text-100);
  --k-dim: var(--text-300);
  --k-faint: var(--text-400);
  --k-accent: var(--accent-main);
  --ds-bg: var(--bg-100);
  --ds-surface: #fff;
  --ds-ink: var(--text-100);
  --ds-muted: var(--text-300);
  --ds-border: rgba(39,26,0,0.08);
  --fg: rgb(39, 37, 30);
  --fg-quiet: rgba(39, 37, 30, 0.65);
  --bg-quiet: rgba(39, 26, 0, 0.07);
  --border-subtle: rgba(39, 26, 0, 0.14);
  --btn-bg: #272520;
  --inverse: #fdfbfa;
  --font-ui: <span class="v">PingFang SC, PingFang TC, -apple-system, BlinkMacSystemFont, Hiragino Sans GB, Microsoft YaHei, sans-serif</span>;
  --color-success: <span class="v">#008000</span>;
  --color-warning: <span class="v">#e07912</span>;
  --color-danger: <span class="v">#e02e2a</span>;
  --color-info: <span class="v">#20808D</span>;
}
